//! `js_normalize` against `fixtures/normalize.json`, generated by Node 26:
//! every code point in all four forms, every code point next to the lowest and
//! highest combining class, the combining-class order of every mark, and
//! random mixed sequences.

mod common;

use std::collections::HashMap;

use common::*;
use jsrt::{JsStr, NormalizationForm};
use serde_json::Value;

const FORMS: [(&str, NormalizationForm); 4] = [
    ("NFC", NormalizationForm::Nfc),
    ("NFD", NormalizationForm::Nfd),
    ("NFKC", NormalizationForm::Nfkc),
    ("NFKD", NormalizationForm::Nfkd),
];

fn single_code_point(cp: u32) -> Vec<u16> {
    match char::from_u32(cp) {
        Some(c) => c.encode_utf16(&mut [0; 2]).to_vec(),
        None => vec![u16::try_from(cp).unwrap()],
    }
}

fn cp_map(v: &Value) -> HashMap<u32, Vec<Vec<u16>>> {
    arr(v)
        .iter()
        .map(|e| {
            let row = arr(e);
            (
                u32::try_from(int(&row[0])).unwrap(),
                row[1..].iter().map(units).collect(),
            )
        })
        .collect()
}

fn check(input: &[u16], form: NormalizationForm, want: &[u16], ctx: &str) {
    assert_eq!(
        input.js_normalize(form).units(),
        want,
        "{form:?} {ctx} input {}",
        hex(input)
    );
    if let Some(s) = well_formed(input) {
        assert_eq!(
            s.js_normalize(form),
            lossy(want),
            "{form:?} {ctx} input {}",
            hex(input)
        );
    }
}

#[test]
fn every_code_point() {
    let f = fixture("normalize.json");
    for (name, form) in FORMS {
        let map = cp_map(&f[format!("single{name}").as_str()]);
        for cp in 0..=0x10FFFF {
            let s = single_code_point(cp);
            let want = map.get(&cp).map_or(&s, |w| &w[0]);
            check(&s, form, want, &format!("U+{cp:04X}"));
        }
    }
}

#[test]
fn every_code_point_next_to_marks() {
    let f = fixture("normalize.json");
    let low = 0x0334u16;
    let high = 0x0345u16;
    for (name, form) in [
        ("NFC", NormalizationForm::Nfc),
        ("NFD", NormalizationForm::Nfd),
    ] {
        let map = cp_map(&f[format!("context{name}").as_str()]);
        for cp in 0..=0x10FFFF {
            let s = single_code_point(cp);
            let plain = s.js_normalize(form);
            let mut after = s.clone();
            after.push(low);
            let mut before = vec![high];
            before.extend_from_slice(&s);
            let (want_after, want_before) = match map.get(&cp) {
                Some(w) => (w[0].clone(), w[1].clone()),
                None => {
                    let mut a = plain.to_vec();
                    a.push(low);
                    let mut b = vec![high];
                    b.extend_from_slice(&plain);
                    (a, b)
                }
            };
            check(&after, form, &want_after, &format!("U+{cp:04X} U+0334"));
            check(&before, form, &want_before, &format!("U+0345 U+{cp:04X}"));
        }
    }
}

#[test]
fn combining_class_order() {
    let f = fixture("normalize.json");
    let ranks: Vec<(u32, i64)> = arr(&f["ranks"])
        .iter()
        .map(|e| (u32::try_from(int(&e[0])).unwrap(), int(&e[1])))
        .collect();
    // One mark per rank is enough to place every other mark.
    let mut reps: Vec<(u32, i64)> = Vec::new();
    for &(cp, rank) in &ranks {
        if reps.last().is_none_or(|&(_, r)| r != rank) {
            reps.push((cp, rank));
        }
    }
    for &(cp, rank) in &ranks {
        for &(rep, rep_rank) in &reps {
            let mut input = single_code_point(cp);
            input.extend(single_code_point(rep));
            let mut swapped = single_code_point(rep);
            swapped.extend(single_code_point(cp));
            let want = if rank > rep_rank { &swapped } else { &input };
            check(
                &input,
                NormalizationForm::Nfd,
                want,
                &format!("U+{cp:04X} U+{rep:04X}"),
            );
        }
    }
}

#[test]
fn random_sequences() {
    let f = fixture("normalize.json");
    for case in arr(&f["random"]) {
        let row = arr(case);
        let input = units(&row[0]);
        for (i, (_, form)) in FORMS.iter().enumerate() {
            check(&input, *form, &units(&row[i + 1]), "random");
        }
    }
}
